create table app_user (id bigint generated by default as identity, full_name varchar(50) not null, user_name varchar(50) not null unique, password varchar(255) not null, role varchar(255) check ((role in ('ROLE_USER','ROLE_ADMIN'))), primary key (id));
create table product (price numeric(38,2) not null, id bigint generated by default as identity, name varchar(255) not null, primary key (id));
